-- MY GYM London - migration: meals library (recipes, foods, 7-day meal plans)
-- Source: the PTPN meal files (seed_common_meals.sql and seed_meal_plans.sql), no photos.
-- Paste into Supabase Dashboard -> SQL Editor -> Run (safe to re-run: ids come from the names, so repeats are skipped).
-- Signed-in members can read these tables; nobody can change them from the app.

begin;

create table if not exists public.foods (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  serving_label text not null default '100 g',
  serving_g numeric not null default 100 check (serving_g > 0),
  kcal numeric not null default 0,        -- macros are per 100 g
  protein numeric not null default 0,
  carbs numeric not null default 0,
  fat numeric not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists public.recipes (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  meal_type text not null default 'lunch' check (meal_type in ('breakfast','lunch','dinner','snack')),
  description text not null default '',
  prep_min int,
  kcal numeric not null default 0,        -- per serving
  protein numeric not null default 0,
  carbs numeric not null default 0,
  fat numeric not null default 0,
  ingredients text[] not null default '{}',
  steps text[] not null default '{}',
  tags text[] not null default '{}',
  image_url text,                         -- not used by the app (photos are off)
  created_at timestamptz not null default now()
);

create table if not exists public.meal_plan_templates (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  goal text not null default 'Balanced',
  kcal int not null default 2000,
  description text not null default '',
  image_url text,
  plan_no int,
  created_at timestamptz not null default now()
);

create table if not exists public.meal_plan_template_items (
  id uuid primary key default gen_random_uuid(),
  template_id uuid not null references public.meal_plan_templates(id) on delete cascade,
  day int not null check (day between 1 and 7),
  meal_type text not null check (meal_type in ('breakfast','lunch','dinner','snack')),
  recipe_id uuid not null references public.recipes(id) on delete cascade,
  servings numeric not null default 1 check (servings > 0),
  sort int not null default 0
);
create index if not exists meal_plan_template_items_tpl on public.meal_plan_template_items (template_id, day);

alter table public.foods enable row level security;
alter table public.recipes enable row level security;
alter table public.meal_plan_templates enable row level security;
alter table public.meal_plan_template_items enable row level security;
drop policy if exists foods_read on public.foods;
create policy foods_read on public.foods for select to authenticated using (true);
drop policy if exists recipes_read on public.recipes;
create policy recipes_read on public.recipes for select to authenticated using (true);
drop policy if exists meal_plans_read on public.meal_plan_templates;
create policy meal_plans_read on public.meal_plan_templates for select to authenticated using (true);
drop policy if exists meal_plan_items_read on public.meal_plan_template_items;
create policy meal_plan_items_read on public.meal_plan_template_items for select to authenticated using (true);
revoke all on public.foods, public.recipes, public.meal_plan_templates, public.meal_plan_template_items from anon, authenticated;
grant select on public.foods, public.recipes, public.meal_plan_templates, public.meal_plan_template_items to authenticated;

create or replace function pg_temp.sid(t text) returns uuid language sql immutable as $$ select md5(t)::uuid $$;


on conflict (id) do nothing;

on conflict (id) do nothing;



on conflict (id) do nothing;

on conflict (id) do nothing;


on conflict (id) do nothing;

on conflict (id) do nothing;


commit;
